export const expandedWorkshops = entries.map(w=>{
  const adaptations=Object.fromEntries(w.levels.map(([age,criterion,children,teacher])=>[age,{
    age,purpose:w.purpose,criterion,evidence:w.evidence,duration_minutes:age===3?25:age===4?30:35,development:{teacher,children},
  }]));
  const age=w.levels[0][0];
  return {id:`taller-biblioteca-${w.id}`,title:w.title,type:w.type,competency_id:w.competency,ages:w.levels.map(l=>l[0]),adaptations,
    ...adaptations[age],materials:w.materials,preparation:w.setup,opening:{teacher:w.opening[0],children:w.opening[1]},
    closure:{teacher:w.closure[0],children:w.closure[1]},resource_key:w.resource};
});
